"""Le guide CODEM, vague 1 : décider et préparer (volume, formule, devis, visite, cartons, jour J).
Règles juridiques (devis, réserves, déclaration de valeur) : INC (Institut national de la consommation), « Le déménagement en 20 questions »."""
INC=('INC : le déménagement en 20 questions','https://www.inc-conso.fr/content/le-demenagement-en-20-questions')
SP='https://www.service-public.gouv.fr/particuliers/vosdroits/'

def _grid():
 """Tableau « qui fait quoi » généré à partir de la grille des formules du site (v1content.GRID)."""
 import build as b
 from v1content import GRID,FORMULES
 t=b.t
 cell=lambda c:{'X':'<td class="y">CODEM</td>','C':f'<td class="n">{t("Vous","You")}</td>','?':f'<td class="q">{t("Selon devis","Per quote")}</td>'}[c]
 head=''.join(f'<th scope="col">{f}</th>' for f in FORMULES)
 rows=''.join(f'<tr><th scope="row">{t(a,c)}</th>'+''.join(cell(x) for x in code)+'</tr>' for a,c,code in GRID)
 return f'<div class="ga-table"><table><thead><tr><th scope="col"></th>{head}</tr></thead><tbody>{rows}</tbody></table></div>'

W1=[
dict(key='volume',slug=('estimer-volume-demenagement','estimate-moving-volume'),theme='preparer',photo='particulier-canape',mn=5,svc='particuliers',
 title=('Estimer le volume de son déménagement','Estimating your moving volume'),
 lead=('Le volume, en mètres cubes, décide du camion, de l’équipe et du prix. Trois méthodes pour l’estimer, des repères meuble par meuble et les oublis à éviter.','Volume, in cubic metres, decides the truck, the team and the price. Three ways to estimate it, item-by-item benchmarks and the things people forget.'),
 sections=[
  (('Pourquoi le volume compte','Why volume matters'),
   ('<p>C’est le premier critère du prix. Il détermine la taille du camion, le nombre de déménageurs et la durée de l’intervention. Un volume sous-estimé, c’est un camion trop petit le jour J. Et si le devis repose uniquement sur vos déclarations, une erreur d’estimation reste à votre charge.</p>',
    '<p>It is the main price factor. It sets the truck size, the number of movers and how long the job takes. An underestimated volume means a truck that is too small on the day. And if the quote relies only on what you declared, an estimation error is your responsibility.</p>')),
  (('Méthode 1 : le repère par la surface','Method 1: the floor-area rule of thumb'),
   ('<p>Repère courant : le volume en mètres cubes représente environ la moitié de la surface en mètres carrés. Un logement bien meublé, avec beaucoup de livres ou de décoration, demande un peu plus. C’est un ordre de grandeur, utile pour un premier budget, pas pour un devis.</p>',
    '<p>A common rule of thumb: the volume in cubic metres is about half the floor area in square metres. A well-furnished home, with lots of books or decoration, needs a little more. It gives an order of magnitude for a first budget, not a quote.</p>')),
  (('Méthode 2 : le calcul pièce par pièce','Method 2: room by room'),
   ('<p>Listez vos meubles pièce par pièce, ajoutez les cartons, et additionnez. Quelques repères utilisés dans <a href="{conseils}#volume">notre calculateur</a> :</p><ul><li>Canapé 3 places : 2 m³</li><li>Lit double et matelas : 2 m³</li><li>Armoire 3 portes : 3 m³</li><li>Buffet ou bahut : 1,5 m³</li><li>Table de salle à manger : 1 m³</li><li>Chaise : 0,2 m³</li></ul>',
    '<p>List your furniture room by room, add the boxes, and total it up. Some benchmarks used in <a href="{conseils}#volume">our calculator</a>:</p><ul><li>3-seater sofa: 2 m³</li><li>Double bed and mattress: 2 m³</li><li>3-door wardrobe: 3 m³</li><li>Sideboard: 1.5 m³</li><li>Dining table: 1 m³</li><li>Chair: 0.2 m³</li></ul>')),
  (('Méthode 3 : la visite technique','Method 3: the survey'),
   ('<p>C’est la plus fiable. Un conseiller voit vos meubles, vos accès et vos objets particuliers, à domicile ou en vidéo. Chez CODEM, la visite est gratuite et le prix devient ferme ensuite. Voir <a href="{g:visite}">comment se passe la visite technique</a>.</p>',
    '<p>It is the most reliable. An adviser sees your furniture, access and special items, at home or by video. At CODEM, the survey is free and the price is fixed afterwards. See <a href="{g:visite}">how the survey works</a>.</p>')),
  (('Les oublis les plus fréquents','The most common omissions'),
   ('<ul><li>La cave, le grenier, le garage et le box.</li><li>Le balcon, la terrasse et le jardin : salon de jardin, pots, barbecue.</li><li>Les vélos, poussettes et jouets d’extérieur.</li><li>Le contenu des placards, souvent plus volumineux qu’on ne le pense.</li></ul>',
    '<ul><li>The cellar, attic, garage and storage unit.</li><li>The balcony, terrace and garden: furniture, pots, barbecue.</li><li>Bikes, pushchairs and outdoor toys.</li><li>What is inside the cupboards, often bulkier than you think.</li></ul>')),
 ],
 tip=('Pendant la visite, ouvrez les placards et emmenez le conseiller à la cave : c’est là que se cache le volume oublié.','During the survey, open the cupboards and take the adviser to the cellar: that is where forgotten volume hides.'),
 faq=[(('Combien de mètres cubes pour un deux-pièces ?','How many cubic metres for a one-bedroom flat?'),('Avec le repère courant, un deux-pièces de 40 m² représente une vingtaine de mètres cubes, un peu plus s’il est bien meublé. La visite permet de le confirmer.','Using the rule of thumb, a 40 m² one-bedroom flat comes to around twenty cubic metres, a little more if well furnished. The survey confirms it.')),
      (('Les cartons comptent-ils dans le volume ?','Do boxes count in the volume?'),('Oui. Ils représentent souvent une part importante du volume total : pensez à les inclure dans votre estimation.','Yes. They often make up a large share of the total volume: include them in your estimate.'))],
 sources=[INC]),

dict(key='formule',slug=('choisir-formule-demenagement','choosing-a-moving-package'),theme='budget',photo='particulier-fauteuil',mn=5,svc='formules',
 title=('Quelle formule de déménagement choisir ?','Which moving package should you choose?'),
 lead=('De Self à Grand Confort : qui emballe, qui démonte, qui déballe. Le tableau complet et nos conseils pour choisir selon votre temps, votre budget et vos objets.','From Self to Grand Confort: who packs, who dismantles, who unpacks. The full table and our advice for choosing by time, budget and belongings.'),
 sections=[
  (('Qui fait quoi, formule par formule','Who does what, package by package'),
   ('{grid}<p class="ga-note">Dans toutes les formules, CODEM protège le mobilier, le met sous housse et assure la manutention et le transport.</p>',
    '{grid}<p class="ga-note">In every package, CODEM protects furniture, puts it under covers, and handles loading and transport.</p>')),
  (('Les prix de départ','Starting prices'),('{prix}','{prix}')),
  (('Comment choisir','How to choose'),
   ('<ul><li><strong>Self</strong> : vous avez du temps et vous préparez tout, cartons et démontage compris. CODEM transporte et manutentionne.</li><li><strong>Self plus</strong> : vous emballez, CODEM démonte, remonte et met en place les meubles.</li><li><strong>Confort</strong> : CODEM emballe et déballe aussi le fragile, la partie la plus délicate. C’est la formule la plus choisie.</li><li><strong>Confort plus</strong> : CODEM emballe tout, fragile et non-fragile. Vous ne gardez que le déballage du non-fragile.</li><li><strong>Grand Confort</strong> : tout est fait pour vous, jusqu’au déballage complet.</li></ul>',
    '<ul><li><strong>Self</strong>: you have time and prepare everything, including boxes and dismantling. CODEM handles loading and transport.</li><li><strong>Self plus</strong>: you pack, CODEM dismantles, reassembles and places the furniture.</li><li><strong>Confort</strong>: CODEM also packs and unpacks fragile items, the most delicate part. It is the most popular package.</li><li><strong>Confort plus</strong>: CODEM packs everything, fragile and non-fragile. You only unpack non-fragile items.</li><li><strong>Grand Confort</strong>: everything is done for you, down to full unpacking.</li></ul>')),
  (('Trois questions pour trancher','Three questions to decide'),
   ('<ol><li>Combien de temps pouvez-vous consacrer aux cartons dans les semaines qui viennent ?</li><li>Avez-vous beaucoup de vaisselle, de verres, de tableaux ou d’objets fragiles ?</li><li>Savez-vous démonter et remonter vos meubles, et avez-vous les outils ?</li></ol><p>Pour une réponse en 30 secondes, faites le <a href="{svc:formules}">quiz des formules</a>.</p>',
    '<ol><li>How much time can you give to packing in the coming weeks?</li><li>Do you have a lot of crockery, glasses, paintings or fragile items?</li><li>Can you dismantle and reassemble your furniture, and do you have the tools?</li></ol><p>For an answer in 30 seconds, take the <a href="{svc:formules}">package quiz</a>.</p>')),
 ],
 tip=('Une formule plus complète coûte plus cher, mais elle vous rend vos soirées et vos week-ends. Comparez avec le temps que vous y passeriez.','A fuller package costs more, but it gives you back your evenings and weekends. Weigh it against the time you would spend.'),
 faq=[(('Peut-on changer de formule après la visite ?','Can I change package after the survey?'),('Oui. Parlez-en à votre conseiller : le devis est mis à jour avec la nouvelle formule avant que vous ne le signiez.','Yes. Talk to your adviser: the quote is updated with the new package before you sign it.')),
      (('Peut-on ajouter une prestation à la carte ?','Can I add a single service?'),('Oui, par exemple l’emballage d’objets fragiles, un monte-meubles ou un garde-meubles. Indiquez-le dans votre demande de devis.','Yes, for example packing fragile items, a furniture lift or storage. Mention it in your quote request.'))],
 sources=[]),

dict(key='devis',slug=('contenu-devis-demenagement','what-a-moving-quote-includes'),theme='budget',photo='agence-codem',mn=6,svc='devis',
 title=('Que comprend un devis de déménagement ?','What does a moving quote include?'),
 lead=('Emballage, démontage, transport, remontage, assurance : ce que doit indiquer un devis, ce que dit la réglementation, et comment le lire avant de signer.','Packing, dismantling, transport, reassembly, insurance: what a quote must show, what the rules say, and how to read it before signing.'),
 sections=[
  (('Un document obligatoire et gratuit','A compulsory, free document'),
   ('<p>Le devis de déménagement est obligatoire et gratuit. Il doit vous être remis avant tout engagement. Une estimation donnée au téléphone ou en ligne n’est qu’une estimation : seul le devis écrit engage le déménageur. Une fois signé, le devis et ses conditions générales forment le contrat.</p>',
    '<p>A moving quote is compulsory and free. It must be given to you before any commitment. A phone or online estimate is only an estimate: only the written quote binds the mover. Once signed, the quote and its terms form the contract.</p>')),
  (('Les informations à y trouver','What it should show'),
   ('<ul><li>Les coordonnées de l’entreprise, votre identité et votre adresse.</li><li>La date ou la période prévue.</li><li>Les adresses de chargement et de livraison, avec les accès.</li><li>Le volume à déménager.</li><li>Le type de transport.</li><li>Le détail des prestations : emballage, démontage, transport, remontage, déballage.</li><li>Le prix hors taxes et toutes taxes comprises.</li></ul>',
    '<ul><li>The company’s details, your identity and address.</li><li>The planned date or period.</li><li>Loading and delivery addresses, with access details.</li><li>The volume to move.</li><li>The type of transport.</li><li>The breakdown of services: packing, dismantling, transport, reassembly, unpacking.</li><li>The price excluding and including tax.</li></ul>')),
  (('Le détail des prestations','The breakdown of services'),
   ('<p>C’est la partie à lire avec attention. Elle dit qui emballe le fragile et le non-fragile, qui démonte et remonte les meubles, qui fournit les cartons, et qui déballe à l’arrivée. Chez CODEM, ce détail correspond à la formule choisie : voir <a href="{g:formule}">quelle formule choisir</a>. Les options figurent aussi : monte-meubles, garde-meubles, objets particuliers.</p>',
    '<p>This is the part to read carefully. It says who packs fragile and non-fragile items, who dismantles and reassembles furniture, who supplies the boxes, and who unpacks on arrival. At CODEM, this matches the package chosen: see <a href="{g:formule}">which package to choose</a>. Options are listed too: furniture lift, storage, special items.</p>')),
  (('Le prix ferme et ses exceptions','The fixed price and its exceptions'),
   ('<p>Le devis doit préciser que le prix est définitif et qu’aucun frais supplémentaire ne peut être facturé, sauf modification expresse du devis. Un supplément reste possible en cas de faute du client, par exemple des informations d’accès inexactes. D’où l’intérêt de signaler tout changement avant le jour J.</p>',
    '<p>The quote must state that the price is final and that no extra charge can be billed, unless the quote is expressly amended. A surcharge remains possible if the client is at fault, for example with inaccurate access information. Hence the value of reporting any change before moving day.</p>')),
  (('Assurance et déclaration de valeur','Insurance and declaration of value'),
   ('<p>Au moment du devis, vous remplissez une déclaration de valeur : elle liste les biens dont la valeur dépasse le plafond d’indemnisation par objet prévu au contrat. Le contrat fixe souvent une limite globale et une limite par objet : vérifiez-les et demandez la déclaration si elle ne vous est pas proposée.</p>',
    '<p>When you get the quote, you fill in a declaration of value: it lists items whose value exceeds the per-item compensation cap in the contract. The contract often sets an overall limit and a per-item limit: check them and ask for the declaration if it is not offered.</p>')),
  (('Signer en toute sérénité','Signing with peace of mind'),
   ('<p>Si vous signez le devis à votre domicile, vous disposez d’un délai de rétractation de 14 jours. Relisez les dates, les adresses, le volume et les prestations, et posez vos questions avant de signer.</p>',
    '<p>If you sign the quote at home, you have a 14-day cooling-off period. Check dates, addresses, volume and services, and ask your questions before signing.</p>')),
 ],
 tip=('Gardez le devis signé et la déclaration de valeur avec vos papiers personnels le jour J, pas dans un carton.','Keep the signed quote and the declaration of value with your personal papers on the day, not in a box.'),
 faq=[(('Le devis est-il payant ?','Is the quote charged for?'),('Non, le devis de déménagement est gratuit. Chez CODEM, la visite technique l’est aussi.','No, a moving quote is free. At CODEM, the survey is free too.')),
      (('Un devis en ligne suffit-il ?','Is an online quote enough?'),('Il donne une estimation. Il repose sur vos déclarations : une erreur de volume ou d’accès peut alors vous être imputée. La visite permet un devis juste et un prix ferme.','It gives an estimate. It relies on what you declare: a volume or access error may then be your responsibility. A survey gives an accurate quote and a fixed price.'))],
 sources=[INC]),

dict(key='comparer',slug=('comparer-devis-demenagement','comparing-moving-quotes'),theme='budget',photo='ancien-02',mn=5,svc='devis',
 title=('Comment comparer plusieurs devis de déménagement','How to compare moving quotes'),
 lead=('Deux devis ne se comparent pas au prix seul. La méthode ligne par ligne pour comparer ce qui est vraiment comparable, et les signaux qui doivent alerter.','Two quotes cannot be compared on price alone. The line-by-line method to compare like with like, and the warning signs.'),
 sections=[
  (('1. Le même volume','1. The same volume'),
   ('<p>Commencez par là. Si un devis annonce nettement moins de mètres cubes que les autres, il sera moins cher sur le papier mais risque d’être revu à la hausse. Un devis établi après visite est plus fiable qu’une estimation à distance.</p>',
    '<p>Start here. If one quote shows far fewer cubic metres than the others, it will look cheaper on paper but may be revised upwards. A quote made after a survey is more reliable than a remote estimate.</p>')),
  (('2. Les mêmes prestations','2. The same services'),
   ('<p>Vérifiez ligne par ligne, pour chaque devis :</p><ul><li>emballage du fragile et du non-fragile ;</li><li>fourniture des cartons et protections ;</li><li>démontage, remontage, mise en place ;</li><li>déballage à l’arrivée ;</li><li>options : monte-meubles, portage, garde-meubles.</li></ul>',
    '<p>Check line by line, for each quote:</p><ul><li>packing of fragile and non-fragile items;</li><li>supply of boxes and protection;</li><li>dismantling, reassembly, placement;</li><li>unpacking on arrival;</li><li>options: furniture lift, long carry, storage.</li></ul>')),
  (('3. Les accès et la date','3. Access and date'),
   ('<p>Étages, ascenseur, distance de portage, stationnement : chaque devis doit en tenir compte. Vérifiez aussi la date ou la période, et la souplesse proposée.</p>',
    '<p>Floors, lift, carrying distance, parking: every quote should take them into account. Also check the date or period, and how flexible it is.</p>')),
  (('4. Le prix ferme et la garantie','4. Fixed price and cover'),
   ('<ul><li>Le prix est-il ferme et définitif, ou s’agit-il d’une estimation ?</li><li>Quelles sont les limites d’indemnisation, globale et par objet ?</li><li>La déclaration de valeur est-elle proposée ? Voir <a href="{g:devis}">ce que comprend un devis</a>.</li></ul>',
    '<ul><li>Is the price fixed and final, or just an estimate?</li><li>What are the compensation limits, overall and per item?</li><li>Is a declaration of value offered? See <a href="{g:devis}">what a quote includes</a>.</li></ul>')),
  (('5. Le sérieux du déménageur','5. The mover’s reliability'),
   ('<ul><li>Une adresse physique et un interlocuteur joignable.</li><li>Des avis clients récents et vérifiables.</li><li>L’inscription au registre des transporteurs, à vérifier.</li><li>Un prix très inférieur aux autres : demandez ce qu’il ne comprend pas.</li></ul>',
    '<ul><li>A physical address and a reachable contact.</li><li>Recent, verifiable client reviews.</li><li>Registration with the carriers’ register, worth checking.</li><li>A price far below the others: ask what it leaves out.</li></ul>')),
 ],
 tip=('Mettez vos devis côte à côte dans un tableau à cinq lignes : volume, prestations, accès, prix ferme, garanties. Les écarts sautent aux yeux.','Put your quotes side by side in a five-row table: volume, services, access, fixed price, cover. The differences jump out.'),
 faq=[(('Combien de devis demander ?','How many quotes should I get?'),('Deux ou trois suffisent pour comparer, à condition qu’ils portent sur le même volume et les mêmes prestations.','Two or three are enough to compare, as long as they cover the same volume and services.')),
      (('Le moins cher est-il le bon choix ?','Is the cheapest the right choice?'),('Pas forcément. Un prix bas peut cacher un volume sous-estimé ou des prestations absentes. Comparez ce qui est inclus avant le montant.','Not necessarily. A low price can hide an underestimated volume or missing services. Compare what is included before the amount.'))],
 sources=[INC,('Service-Public : je déménage en France',SP+'F14128')]),

dict(key='visite',slug=('visite-technique-demenagement','moving-survey'),theme='preparer',photo='particulier-immeuble',mn=4,svc='devis',
 title=('La visite technique : à quoi sert-elle ?','The moving survey: what is it for?'),
 lead=('À domicile ou en vidéo, la visite permet un devis juste et un prix ferme. Comment elle se déroule et comment la préparer en dix minutes.','At home or by video, the survey gives an accurate quote and a fixed price. How it works and how to prepare in ten minutes.'),
 sections=[
  (('À quoi elle sert','What it is for'),
   ('<p>La loi ne l’impose pas, mais elle change tout. Le conseiller évalue le volume réel, repère les accès, les meubles à démonter et les objets particuliers. Le devis qui suit est juste, et vous évitez les mauvaises surprises le jour J.</p>',
    '<p>The law does not require it, but it changes everything. The adviser assesses the real volume, checks access, furniture to dismantle and special items. The resulting quote is accurate, and you avoid surprises on the day.</p>')),
  (('Comment elle se déroule','How it works'),
   ('<ol><li>Le conseiller fait le tour des pièces avec vous, placards, cave et extérieurs compris.</li><li>Il note les accès : étage, ascenseur, escaliers, stationnement.</li><li>Il vous demande ce qui part, ce qui reste et ce qui va en garde-meubles.</li><li>Il vous conseille sur la formule et les options.</li><li>Vous recevez ensuite un devis écrit et détaillé.</li></ol>',
    '<ol><li>The adviser walks through the rooms with you, including cupboards, cellar and outdoor areas.</li><li>They note access: floor, lift, stairs, parking.</li><li>They ask what goes, what stays and what goes into storage.</li><li>They advise on package and options.</li><li>You then receive a written, detailed quote.</li></ol>')),
  (('À domicile ou en vidéo','At home or by video'),
   ('<p>La visite à domicile reste la plus complète. La visite en vidéo est pratique si vous êtes loin, pressé, ou pour un petit volume : vous faites le tour du logement avec votre téléphone, le conseiller vous guide.</p>',
    '<p>A home survey is the most thorough. A video survey is handy if you are far away, short of time, or moving a small volume: you walk around the home with your phone while the adviser guides you.</p>')),
  (('La préparer en dix minutes','Preparing in ten minutes'),
   ('<ul><li>Listez ce qui ne part pas : meubles vendus, donnés ou laissés.</li><li>Notez les objets particuliers : piano, tableaux, miroirs, objets de valeur.</li><li>Rassemblez les infos de l’arrivée : étage, ascenseur et ses dimensions, stationnement.</li><li>Préparez vos questions sur les dates, la formule et l’assurance.</li></ul>',
    '<ul><li>List what is not going: furniture sold, given away or left behind.</li><li>Note special items: piano, paintings, mirrors, valuables.</li><li>Gather details of the new home: floor, lift and its dimensions, parking.</li><li>Prepare your questions on dates, package and insurance.</li></ul>')),
 ],
 tip=('Ayez une photo des accès de votre nouveau logement : la porte d’entrée, l’escalier, l’ascenseur. Le conseiller prévoit tout de suite le bon matériel.','Have a photo of the access at your new home: front door, stairs, lift. The adviser can plan the right equipment straight away.'),
 faq=[(('La visite est-elle payante ?','Is the survey charged for?'),('Chez CODEM, non : la visite est gratuite et sans engagement, à domicile ou en vidéo.','At CODEM, no: the survey is free and with no obligation, at home or by video.')),
      (('Faut-il que le logement soit rangé ?','Does the home need to be tidy?'),('Non. Le conseiller a surtout besoin de voir l’intérieur des placards, la cave et les accès, tels qu’ils sont.','No. The adviser mainly needs to see inside cupboards, the cellar and the access, as they are.'))],
 sources=[INC]),

dict(key='cartons',slug=('choisir-cartons-demenagement','choosing-moving-boxes'),theme='emballage',photo='ancien-17',mn=4,svc='cartons',
 title=('Quels cartons et protections choisir ?','Which boxes and protection to choose?'),
 lead=('Cartons standard, cartons livres, penderies, papier bulle, housses : le bon matériel pour chaque type d’objet, et nos conseils pour ne pas en manquer.','Standard boxes, book boxes, wardrobe boxes, bubble wrap, covers: the right materials for each kind of item, and our advice so you do not run short.'),
 sections=[
  (('Les cartons','Boxes'),
   ('<ul><li><strong>Petits cartons</strong> : livres, vaisselle, objets lourds. Plus le contenu est lourd, plus le carton doit être petit.</li><li><strong>Cartons standard</strong> : la majorité de vos affaires.</li><li><strong>Grands cartons</strong> : linge, couettes, coussins, objets légers et volumineux.</li><li><strong>Cartons à séparations</strong> : verres et bouteilles.</li><li><strong>Penderies</strong> : les vêtements voyagent sur cintres.</li><li><strong>Cartons archives</strong> : dossiers et documents.</li></ul>',
    '<ul><li><strong>Small boxes</strong>: books, crockery, heavy items. The heavier the contents, the smaller the box.</li><li><strong>Standard boxes</strong>: most of your belongings.</li><li><strong>Large boxes</strong>: linen, duvets, cushions, light bulky items.</li><li><strong>Divided boxes</strong>: glasses and bottles.</li><li><strong>Wardrobe boxes</strong>: clothes travel on hangers.</li><li><strong>Archive boxes</strong>: files and documents.</li></ul>')),
  (('Les protections','Protection'),
   ('<ul><li>Papier d’emballage blanc et papier bulle pour le fragile.</li><li>Housses pour matelas et sommiers.</li><li>Couvertures de déménagement pour les meubles.</li><li>Ruban adhésif solide, marqueur et étiquettes.</li></ul>',
    '<ul><li>White packing paper and bubble wrap for fragile items.</li><li>Covers for mattresses and bases.</li><li>Moving blankets for furniture.</li><li>Strong tape, marker and labels.</li></ul>')),
  (('Neufs ou de récupération ?','New or second-hand?'),
   ('<p>Des cartons récupérés conviennent pour le linge ou les objets légers, s’ils sont propres et rigides. Pour la vaisselle, les livres et le fragile, préférez des cartons solides, faits pour le déménagement : un fond qui cède, c’est de la casse assurée.</p>',
    '<p>Reused boxes are fine for linen or light items, if clean and rigid. For crockery, books and fragile items, choose sturdy boxes made for moving: a bottom that gives way means guaranteed breakage.</p>')),
  (('Combien en prévoir ?','How many do you need?'),
   ('<p>Tout dépend du volume et de votre façon de ranger. Le plus simple est de demander une quantité conseillée lors du devis : CODEM vend les cartons et fournitures utilisés par ses équipes, en quantités adaptées à votre volume. Voir <a href="{svc:cartons}">cartons et fournitures</a>.</p>',
    '<p>It depends on your volume and how you store things. The easiest way is to ask for a recommended quantity with your quote: CODEM sells the boxes and supplies its teams use, in quantities suited to your volume. See <a href="{svc:cartons}">boxes and supplies</a>.</p>')),
 ],
 tip=('Montez chaque carton avec une croix d’adhésif sous le fond, pas un seul trait : c’est ce qui l’empêche de s’ouvrir quand on le soulève.','Tape the bottom of each box with a cross, not a single strip: that is what stops it opening when lifted.'),
 faq=[(('Où acheter des cartons de déménagement ?','Where can I buy moving boxes?'),('CODEM vend cartons, penderies, papier bulle et housses à Nogent-sur-Marne, en quantités conseillées selon votre volume.','CODEM sells boxes, wardrobe boxes, bubble wrap and covers in Nogent-sur-Marne, in quantities suited to your volume.')),
      (('Faut-il emballer les vêtements ?','Do clothes need packing?'),('Les vêtements suspendus voyagent dans des penderies, sur leurs cintres. Les vêtements pliés vont dans des cartons standard ou restent dans les tiroirs si le meuble n’est pas démonté.','Hanging clothes travel in wardrobe boxes, on their hangers. Folded clothes go in standard boxes or stay in drawers if the furniture is not dismantled.'))],
 sources=[]),

dict(key='etiqueter',slug=('etiqueter-cartons-demenagement','labelling-moving-boxes'),theme='emballage',photo='ancien-13',mn=4,svc='cartons',
 title=('Répartir et étiqueter ses cartons','Packing and labelling your boxes'),
 lead=('Un bon étiquetage fait gagner des heures à l’arrivée. La méthode simple pour que chaque carton aille directement dans la bonne pièce.','Good labelling saves hours on arrival. The simple method so every box goes straight to the right room.'),
 sections=[
  (('Un carton, une pièce','One box, one room'),
   ('<p>Emballez pièce par pièce et ne mélangez pas les contenus. Un carton « cuisine » ne doit contenir que des affaires de cuisine : il sera posé directement dans la cuisine, et vous saurez où chercher.</p>',
    '<p>Pack room by room and do not mix contents. A “kitchen” box should only hold kitchen items: it will go straight into the kitchen, and you will know where to look.</p>')),
  (('Ce qu’il faut écrire','What to write'),
   ('<ul><li>La pièce de destination, dans le nouveau logement.</li><li>Un numéro de carton.</li><li>Le contenu en quelques mots.</li><li>« FRAGILE » et le sens du carton si besoin.</li></ul><p>Écrivez sur deux côtés et sur le dessus : le carton reste lisible même empilé.</p>',
    '<ul><li>The destination room, in the new home.</li><li>A box number.</li><li>The contents in a few words.</li><li>“FRAGILE” and “this way up” if needed.</li></ul><p>Write on two sides and on top: the box stays readable even when stacked.</p>')),
  (('Le code couleur','Colour coding'),
   ('<p>Attribuez une couleur à chaque pièce : une étiquette ou un ruban adhésif de couleur sur chaque carton, et la même couleur collée sur la porte de la pièce à l’arrivée. Les déménageurs déposent les cartons au bon endroit, sans vous demander.</p>',
    '<p>Give each room a colour: a coloured label or tape on every box, and the same colour stuck on the room’s door on arrival. Movers put boxes in the right place without asking you.</p>')),
  (('La liste qui va avec','The list that goes with it'),
   ('<p>Tenez une liste simple : numéro, pièce, contenu. Sur votre téléphone, une photo du contenu avant de fermer le carton suffit. En cas de doute à l’arrivée, vous retrouvez tout en quelques secondes.</p>',
    '<p>Keep a simple list: number, room, contents. On your phone, a photo of the contents before closing the box is enough. If in doubt on arrival, you find everything in seconds.</p>')),
  (('Bien répartir le poids','Spreading the weight'),
   ('<ul><li>Le lourd en bas, le léger au-dessus.</li><li>Des cartons que vous pouvez soulever facilement.</li><li>Les cartons à ouvrir en premier marqués « PRIORITAIRE ».</li></ul>',
    '<ul><li>Heavy items at the bottom, light ones on top.</li><li>Boxes you can lift easily.</li><li>Boxes to open first marked “PRIORITY”.</li></ul>')),
 ],
 tip=('Collez un plan simple du nouveau logement près de l’entrée, avec les couleurs des pièces : toute l’équipe s’y retrouve au premier coup d’œil.','Stick a simple plan of the new home by the entrance, with the room colours: the whole team finds its way at a glance.'),
 faq=[(('Faut-il numéroter les cartons ?','Should boxes be numbered?'),('C’est très utile : avec une liste, vous vérifiez à l’arrivée que tous les cartons sont là, et vous retrouvez vite un contenu.','It is very useful: with a list, you check on arrival that every box is there, and quickly find what you need.')),
      (('Que mettre dans le carton prioritaire ?','What goes in the priority box?'),('Le nécessaire des premiers jours : chargeurs, papiers, draps, nécessaire de toilette, une casserole, de quoi faire un café.','Essentials for the first days: chargers, papers, sheets, toiletries, a saucepan, coffee-making kit.'))],
 sources=[]),

dict(key='jourj',slug=('veille-et-jour-du-demenagement','day-before-and-moving-day'),theme='preparer',photo='ancien-19',mn=5,svc='particuliers',
 title=('La veille et le jour du déménagement','The day before and moving day'),
 lead=('Ce qu’il faut préparer la veille, comment se passe la journée, et ce qu’il faut vérifier à l’arrivée avant de signer.','What to prepare the day before, how the day goes, and what to check on arrival before signing.'),
 sections=[
  (('La veille','The day before'),
   ('<ul><li>Videz, débranchez et dégivrez réfrigérateur et congélateur, porte ouverte.</li><li>Débranchez la machine à laver et videz-la bien.</li><li>Préparez un sac personnel : papiers, clés, chargeurs, médicaments, bijoux.</li><li>Dégagez les passages et rassemblez les cartons près de l’entrée.</li><li>Prévenez le gardien ou le syndic, réservez l’ascenseur si c’est possible.</li><li>Vérifiez que l’autorisation de stationnement est en place.</li><li>Organisez la garde des enfants et des animaux.</li></ul>',
    '<ul><li>Empty, unplug and defrost the fridge and freezer, door open.</li><li>Unplug the washing machine and drain it fully.</li><li>Pack a personal bag: papers, keys, chargers, medicines, jewellery.</li><li>Clear walkways and gather boxes near the entrance.</li><li>Tell the caretaker or managing agent, book the lift if possible.</li><li>Check the parking permit is in place.</li><li>Arrange care for children and pets.</li></ul>')),
  (('Au départ','At departure'),
   ('<ol><li>Accueillez l’équipe et faites le tour des pièces avec le chef d’équipe.</li><li>Montrez le fragile, ce qui ne part pas et ce qui va en garde-meubles.</li><li>Restez joignable pendant le chargement.</li><li>Relevez les compteurs, faites l’état des lieux de sortie, et un dernier tour : placards, cave, balcon.</li></ol>',
    '<ol><li>Welcome the team and walk through the rooms with the team leader.</li><li>Point out fragile items, what stays and what goes into storage.</li><li>Stay reachable during loading.</li><li>Read the meters, do the move-out inspection, and a final check: cupboards, cellar, balcony.</li></ol>')),
  (('À l’arrivée','On arrival'),
   ('<ul><li>Arrivez avant l’équipe pour ouvrir et indiquer les pièces.</li><li>Faites placer les meubles là où vous les voulez : c’est plus simple le jour même.</li><li>Vérifiez les meubles et les cartons avant de signer le bulletin de livraison.</li></ul>',
    '<ul><li>Arrive before the team to open up and show the rooms.</li><li>Have the furniture placed where you want it: easier on the day.</li><li>Check the furniture and boxes before signing the delivery note.</li></ul>')),
  (('En cas de dommage','If something is damaged'),
   ('<p>Si vous constatez un dommage à la livraison, décrivez-le précisément sur le bulletin de livraison. Si vous le découvrez après le départ de l’équipe, vous avez 10 jours après la livraison pour le signaler par lettre recommandée avec accusé de réception. Un simple e-mail ne suffit pas.</p>',
    '<p>If you notice damage on delivery, describe it precisely on the delivery note. If you find it after the team has left, you have 10 days after delivery to report it by registered letter with acknowledgement of receipt. A plain email is not enough.</p>')),
 ],
 tip=('Gardez à portée de main de l’eau, de quoi grignoter et un rouleau d’essuie-tout : la journée est longue, pour vous comme pour l’équipe.','Keep water, snacks and a kitchen roll within reach: it is a long day, for you and for the team.'),
 faq=[(('Faut-il prévoir quelque chose pour l’équipe ?','Should I provide anything for the team?'),('Rien d’obligatoire. Des passages dégagés, une place pour le camion et un accès à un point d’eau facilitent la journée.','Nothing compulsory. Clear walkways, a space for the truck and access to water make the day easier.')),
      (('Faut-il être présent toute la journée ?','Do I need to be there all day?'),('Au moins au début du chargement et à la livraison, vous ou une personne de confiance, pour donner les consignes et vérifier l’arrivée des biens.','At least at the start of loading and at delivery, you or someone you trust, to give instructions and check your belongings.'))],
 sources=[INC]),
]
